// SPEC 10 Paso 3: normalizar filas del Sheet (12 columnas exactas).
// Entrada: un item por fila del Sheet, headers en minusculas.
// Salida: un item por fila -> {12 campos normalizados} o {_error, id} si falla.
// - id: texto con trim(); vacio => {_error:'id vacío'}.
// - duplicado en Sheet (mismo id con trim exacto) => {_error:'duplicado en Sheet: <id>'}.
// - texto (clave,variante,descripcion,informacion,disponible,marca,categoria,precioant,precio): trim() o NULL si vacio. Precios TAL CUAL, sin normalizar $.
// - existencias: parseInt(...) || 0. destacado: '1'/'TRUE' (trim+upper) => true, resto => false.
// Los errores no detienen el flujo; CodeDiff/CodeResumen los recogen via $items('CodeNormalizar').
const COLUMNAS_TEXTO = ['clave', 'variante', 'descripcion', 'informacion', 'disponible', 'marca', 'categoria', 'precioant', 'precio'];
function textoONulo(v) {
  if (v === null || v === undefined) return null;
  const t = String(v).trim();
  return t === '' ? null : t;
}
function aEntero(v) {
  const n = parseInt(String(v ?? '').trim(), 10);
  return Number.isNaN(n) ? 0 : n;
}
function aBool(v) {
  const t = String(v ?? '').trim().toUpperCase();
  return t === '1' || t === 'TRUE' || t === 'T' || t === 'YES' || t === 'Y';
}
const items = $input.all();
const vistos = new Set();
const salida = [];
for (let i = 0; i < items.length; i++) {
  const row = (items[i] && items[i].json) || {};
  const idCrudo = row.id;
  const id = (idCrudo === null || idCrudo === undefined) ? '' : String(idCrudo).trim();
  const idx = i + 2;
  if (id === '') {
    salida.push({ json: { _error: 'id vacío', id: '', _sheet_index: idx } });
    continue;
  }
  if (vistos.has(id)) {
    salida.push({ json: { _error: 'duplicado en Sheet: ' + id, id: id, _sheet_index: idx } });
    continue;
  }
  vistos.add(id);
  const norm = { id: id, _sheet_index: idx };
  for (const c of COLUMNAS_TEXTO) norm[c] = textoONulo(row[c]);
  norm.existencias = aEntero(row.existencias);
  norm.destacado = aBool(row.destacado);
  salida.push({ json: norm });
}
return salida;

// Puerta de 1 item: colapsa los N items de CodeNormalizar a un solo item.
// Sin esto, PostgresSelect (executeQuery) se ejecuta 1 vez POR ITEM (~477-2433 SELECTs identicos) y agota el pool / causa timeout.
// CodeDiff sigue leyendo el Sheet via $items('CodeNormalizar'), asi que no se pierde nada.
return [{ json: { go: 1 } }];

// SPEC 10 Paso 4: diff campo por campo (Sheet normalizado vs Postgres).
// Entrada directa ($input): filas de Postgres (PostgresSelect, 12 columnas).
// Sheet normalizado via $items('CodeNormalizar') (incluye {_error} que aqui se ignoran; los cuenta CodeResumen).
// Salida: solo filas nuevas o con al menos un campo distinto -> {accion:'insert'|'update', fila:{12 campos}, _sheet_index}.
// Sin cambios => no se emite (segunda ejecucion sin tocar el Sheet => salida vacia).
// Ids en DB ausentes en el Sheet se ignoran (sin UPDATE ni DELETE).
const COLUMNAS_TEXTO = ['clave', 'variante', 'descripcion', 'informacion', 'disponible', 'marca', 'categoria', 'precioant', 'precio'];
function normTexto(v) {
  if (v === null || v === undefined) return null;
  const t = String(v).trim();
  return t === '' ? null : t;
}
function normInt(v) {
  const n = parseInt(String(v ?? '').trim(), 10);
  return Number.isNaN(n) ? 0 : n;
}
function normBool(v) {
  if (typeof v === 'boolean') return v;
  const t = String(v ?? '').trim().toUpperCase();
  return t === '1' || t === 'TRUE' || t === 'T' || t === 'YES' || t === 'Y';
}
function distinta(sheet, db) {
  for (const c of COLUMNAS_TEXTO) {
    if (normTexto(sheet[c]) !== normTexto(db[c])) return true;
  }
  if (normInt(sheet.existencias) !== normInt(db.existencias)) return true;
  if (normBool(sheet.destacado) !== normBool(db.destacado)) return true;
  return false;
}
const dbItems = $input.all();
let sheetItems = [];
try { sheetItems = $items('CodeNormalizar'); } catch (e) { sheetItems = []; }
const dbPorId = new Map();
for (const it of dbItems) {
  const r = (it && it.json) || {};
  const id = (r.id === null || r.id === undefined) ? '' : String(r.id).trim();
  if (id !== '' && !dbPorId.has(id)) dbPorId.set(id, r);
}
const salida = [];
for (const it of sheetItems) {
  const s = (it && it.json) || {};
  if (s._error) continue;
  const id = s.id;
  const fila = { id: id };
  for (const c of COLUMNAS_TEXTO) fila[c] = (s[c] === undefined ? null : s[c]);
  fila.existencias = s.existencias;
  fila.destacado = s.destacado;
  const db = dbPorId.get(id);
  if (!db) {
    salida.push({ json: { accion: 'insert', fila: fila, _sheet_index: s._sheet_index } });
  } else if (distinta(s, db)) {
    salida.push({ json: { accion: 'update', fila: fila, _sheet_index: s._sheet_index } });
  }
}
return salida;

// SPEC 10 Paso 6: resumen final visible en Executions de n8n.
// Fuentes (via $items, porque PostgresSelect y el loop cortan el flujo directo):
// - CodeNormalizar: todas las filas del Sheet (validas + {_error, id}).
// - CodeDiff: solo {accion:'insert'|'update', fila} intentadas.
// - $input: salida done del LoopUpsert = resultados de PostgresUpsert. Items con .error (o json.error) = fallos SQL absorbidos por onError:continue.
// Salida: un solo item {leidas, actualizadas, insertadas, sin_cambios, errores, detalle_errores}.
// actualizadas/insertadas = UPSERTs intentados (en el camino feliz = aplicados). Si hubo errores SQL, el detalle lo indica.
let norm = [];
try { norm = $items('CodeNormalizar'); } catch (e) { norm = []; }
let diff = [];
try { diff = $items('CodeDiff'); } catch (e) { diff = []; }
const res = $input.all();
const leidas = norm.length;
const detalle_errores = [];
let erroresNorm = 0;
for (const it of norm) {
  const j = (it && it.json) || {};
  if (j._error) {
    erroresNorm++;
    detalle_errores.push({ id: (j.id === undefined || j.id === null) ? '' : String(j.id), motivo: String(j._error), fila_sheet: j._sheet_index || null });
  }
}
let actualizadas = 0, insertadas = 0;
for (const it of diff) {
  const j = (it && it.json) || {};
  if (j.accion === 'update') actualizadas++;
  else if (j.accion === 'insert') insertadas++;
}
let erroresSql = 0;
for (const it of res) {
  const errObj = (it && it.error) || ((it && it.json && it.json.error) ? it.json.error : null);
  if (errObj) {
    erroresSql++;
    const j = (it && it.json) || {};
    const fid = (j.fila && j.fila.id !== undefined) ? String(j.fila.id) : (j.id !== undefined ? String(j.id) : '');
    const motivo = (errObj && errObj.message) ? String(errObj.message) : String(errObj);
    detalle_errores.push({ id: fid, motivo: 'sql: ' + motivo.slice(0, 300), fila_sheet: j._sheet_index || null });
  }
}
const errores = erroresNorm + erroresSql;
const validas = leidas - erroresNorm;
const sin_cambios = Math.max(0, validas - (actualizadas + insertadas));
return [{ json: { leidas: leidas, actualizadas: actualizadas, insertadas: insertadas, sin_cambios: sin_cambios, errores: errores, detalle_errores: detalle_errores } }];
